// A request's messages less their cache breakpoints, which move to the
// newest message on every request and are not part of what is cached.
json without_breakpoints(json value)
{
    if (value.is_object()) {
        value.erase("cache_control");
        for (auto& [key, child] : value.items())
            child = without_breakpoints(child);
    } else if (value.is_array()) {
        for (json& child : value)
            child = without_breakpoints(child);
    }
    return value;
}

