// A provider reads back from its cache only the unchanged opening of a
// request, and the host's replay of a finished turn is a shorter retelling
// (no thinking, no pictures, no workspace beside the person's words) that
// matches nothing it cached. So the chat's finished turns open the next turn
// as they were sent, when the history the host sends for it is exactly what
// it sent for the last turn followed by its replay of that turn. Anything
// else, such as another chat, a history trimmed or restored, or a note
// between turns, is sent as the host replays it.
void ProviderAgent::carry_finished_turns(const AgentRequest& request)
{
    m_carried_replay.clear();
    if (!m_finished || request.conversation_id.empty() || m_finished->conversation_id != request.conversation_id ||
        m_finished->instructions != m_transcript.instructions || !same_tools(m_finished->tools, m_transcript.tools))
        return;
    const FinishedTurns&                         finished = *m_finished;
    const std::vector<AgentConversationContext>& history  = request.conversation;
    const std::size_t                            kept     = finished.opening.size() + finished.replay.size();
    if (history.size() < kept || !std::equal(finished.opening.begin(), finished.opening.end(), history.begin(), same_entry) ||
        !std::equal(finished.replay.begin(), finished.replay.end(), history.begin() + finished.opening.size(), same_entry))
        return;
    // The rest is the replay of the last turn: its user message, if the host
    // replays one, then its words and the calls the host ran, in order.
    std::vector<std::string> calls;
    for (auto entry = history.begin() + kept; entry != history.end(); ++entry) {
        if (!entry->call_id.empty())
            calls.push_back(entry->call_id);
        else if (entry->role != "assistant" && !(entry->role == "user" && entry == history.begin() + kept))
            return;
    }
    // Carried turns are sent whole; past this the host's replay, which trims
    // to its own budget, takes over again from the next turn.
    constexpr std::size_t kCarriedBytes = 128 * 1024;
    if (calls != finished.last_calls || carried_bytes(finished.turns) > kCarriedBytes)
        return;
    m_carried_replay.assign(history.begin() + finished.opening.size(), history.end());
    m_transcript.opening = finished.opening;
    m_transcript.carried = finished.turns;
}

